&lt;div style=&quot;float:right; padding: 0 0 8px 8px&quot;&gt;
&lt;table&gt;
&lt;tr style=&quot;vertical-align:bottom&quot;&gt;
&lt;td style=&quot;display:none; background-color: #f3efe2; border: 1px solid #4b3124; padding: 2px; width:250px; text-align: left&quot;&gt;
&lt;table&gt;&lt;tr style=&quot;vertical-align: top&quot;&gt;&lt;td&gt;
&lt;b&gt;&lt;i&gt;Sur une id&#233;e d&#39;Arkane&lt;/i&gt;&lt;/b&gt;&lt;/td&gt;&lt;td style=&quot;height:30px&quot;&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/td&gt;
&lt;td&gt;&lt;img style=&quot;width:30px; cursor:pointer&quot; src=&quot;/images/pathfinder/wiki/ibase.png&quot; title=&quot;Cliquez pour afficher/cacher une d&#233;sambigu&#239;sation (homonymes, redirections, etc...)&quot; alt=&quot;Cliquez pour afficher/cacher l&#39;information&quot; onclick=&quot;
var cible = this.parentNode.previousSibling.previousSibling;
if (cible.style.display==&#39;none&#39;) {
  $(cible).show(&#39;slide&#39;);
  $(this).fadeTo(500,0.4);
} else {
  $(cible).hide(&#39;slide&#39;);
  $(this).fadeTo(500,1);
}&quot; ONMOUSEOVER=&quot;this.src = &#39;/images/pathfinder/wiki/ialt.png&#39;;&quot;
ONMOUSEOUT=&quot;this.src = &#39;/images/pathfinder/wiki/ibase.png&#39;;&quot; /&gt;&lt;/td&gt;
&lt;/tr&gt;&lt;/table&gt;&lt;/div&gt;&lt;i&gt;La comp&#233;tence &lt;a class=&quot;pagelink&quot; href=&quot;Linguistique.html&quot; title=&quot;Linguistique&quot;&gt;Linguistique&lt;/a&gt; offre de nombreuses options mais votre personnage peut souhaiter apprendre d&#39;autres langues que celles d&#233;j&#224; propos&#233;es et certains sorts ou capacit&#233;s vous permettent de parler ou de comprendre d&#39;autres langues parl&#233;es par des cr&#233;atures plus inattendues.&lt;/i&gt;&lt;br /&gt;&lt;br /&gt;Certains sorts comme &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Communication-Avec-Les-Animaux.html&quot; title=&quot;Communication avec les animaux&quot;&gt;communication avec les animaux&lt;/a&gt;&lt;/i&gt; vous permettent de parler avec des animaux et d&#39;autres du type &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Communication-Avec-Les-Plantes.html&quot; title=&quot;Communication avec les plantes&quot;&gt;Communication avec les plantes&lt;/a&gt;&lt;/i&gt; vous permettent de le faire avec les plantes et les cr&#233;atures de type plante.&lt;br /&gt;&lt;br /&gt;Cette page vous propose de recenser les langues et langages que vous pouvez croiser dans le cadre du jeu. Si vous souhaitez apprendre une de ces langues, vous &#234;tes invit&#233;s &#224; interroger votre MJ au pr&#233;alable.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Les langues des races extraordinaires et des monstres des bestiaires&lt;a class=&quot;headeranchor&quot; id=&quot;Les_langues_des_races_extraordinaires_et_des_monstres_des_bestiaires_0&quot; href=&quot;#Les_langues_des_races_extraordinaires_et_des_monstres_des_bestiaires_0&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Outre les langages de base des races diverses dont l&#39;&#233;num&#233;ration est donn&#233;e dans la comp&#233;tence &lt;a class=&quot;pagelink&quot; href=&quot;Linguistique.html&quot; title=&quot;Linguistique&quot;&gt;Linguistique&lt;/a&gt;, il en existe d&#39;autres propres &#224; d&#39;autres races ou d&#39;autres monstres.
&lt;ul&gt;&lt;li&gt;Aboleth (&lt;a class=&quot;pagelink&quot; href=&quot;Aboleth.html&quot; title=&quot;Alghollthu, Aboleth&quot;&gt;aboleths&lt;/a&gt;)&lt;/li&gt;&lt;li&gt;Adlet (&lt;a class=&quot;pagelink&quot; href=&quot;Adlet.html&quot; title=&quot;Adlet&quot;&gt;adlets&lt;/a&gt;)&lt;/li&gt;&lt;li&gt;Cyclope (&lt;a class=&quot;pagelink&quot; href=&quot;Cyclope.html&quot; title=&quot;Cyclope&quot;&gt;cyclopes&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Grand-Cyclope.html&quot; title=&quot;Cyclope, Grand cyclope&quot;&gt;grands cyclopes&lt;/a&gt;)&lt;/li&gt;&lt;li&gt;Bourbi&#233;rin (&lt;a class=&quot;pagelink&quot; href=&quot;Bourbi&#233;rin.html&quot; title=&quot;Bourbi&#233;rin&quot;&gt;bourbi&#233;rins&lt;/a&gt;)&lt;/li&gt;&lt;li&gt;D’ziriak (&lt;a class=&quot;pagelink&quot; href=&quot;Dziriak.html&quot; title=&quot;Dziriak&quot;&gt;d&#39;ziriaks&lt;/a&gt;)&lt;/li&gt;&lt;li&gt;Girtablilu (&lt;a class=&quot;pagelink&quot; href=&quot;Girtablilu.html&quot; title=&quot;Girtablilu&quot;&gt;girtablilus&lt;/a&gt;)&lt;/li&gt;&lt;li&gt;Grippli (&lt;a class=&quot;pagelink&quot; href=&quot;Grippli.html&quot; title=&quot;Grippli&quot;&gt;gripplis&lt;/a&gt;)&lt;/li&gt;&lt;li&gt;Huline (&lt;a class=&quot;pagelink&quot; href=&quot;Homme-F&#233;lin.html&quot; title=&quot;Homme-f&#233;lin&quot;&gt;hommes-f&#233;lins&lt;/a&gt;)&lt;/li&gt;&lt;li&gt;Kasatha (&lt;a class=&quot;pagelink&quot; href=&quot;Kasatha.html&quot; title=&quot;Kasatha&quot;&gt;kasathas&lt;/a&gt;)&lt;/li&gt;&lt;li&gt;Kech (&lt;a class=&quot;pagelink&quot; href=&quot;Kech.html&quot; title=&quot;Kech&quot;&gt;kechs&lt;/a&gt;)&lt;/li&gt;&lt;li&gt;Munavri (&lt;a class=&quot;unknownlink&quot; href=&quot;Munavri.html&quot; title=&quot;Pathfinder-RPG.munavri&quot;&gt;munavris&lt;/a&gt;)&lt;/li&gt;&lt;li&gt;Obscurien/Obscur (&lt;a class=&quot;pagelink&quot; href=&quot;Fureteur-Obscur.html&quot; title=&quot;Obscurien, Fureteur obscur&quot;&gt;fureteur obscur&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Traqueur-Obscur.html&quot; title=&quot;Obscurien, Traqueur obscur&quot;&gt;traqueur obscur&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Tueur-Obscur.html&quot; title=&quot;Obscurien, Tueur obscur&quot;&gt;tueur obscur&lt;/a&gt;)&lt;/li&gt;&lt;li&gt;Reptoide (&lt;a class=&quot;unknownlink&quot; href=&quot;Reptoide.html&quot; title=&quot;Pathfinder-RPG.reptoide&quot;&gt;reptoides&lt;/a&gt;)&lt;/li&gt;&lt;li&gt;Samsaran (&lt;a class=&quot;pagelink&quot; href=&quot;Samsaran-(Race).html&quot; title=&quot;Les samsarans&quot;&gt;samsarans&lt;/a&gt;)&lt;/li&gt;&lt;li&gt;Sasquatch (&lt;a class=&quot;pagelink&quot; href=&quot;Sasquatch.html&quot; title=&quot;Sasquatch&quot;&gt;sasquatchs&lt;/a&gt;)&lt;/li&gt;&lt;li&gt;Sphinx (&lt;a class=&quot;pagelink&quot; href=&quot;Androsphinx.html&quot; title=&quot;Sphinx, Androsphinx&quot;&gt;androsphinx&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Criosphinx.html&quot; title=&quot;Sphinx, Criosphinx&quot;&gt;criosphinx&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Gynosphinx.html&quot; title=&quot;Sphinx, Gynosphinx&quot;&gt;gynosphinx&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Hi&#233;racosphinx.html&quot; title=&quot;Sphinx, Hi&#233;racosphinx&quot;&gt;hi&#233;racosphinx&lt;/a&gt;)&lt;/li&gt;&lt;li&gt;Strix (&lt;a class=&quot;pagelink&quot; href=&quot;Strix-(Race).html&quot; title=&quot;Les strix&quot;&gt;strix&lt;/a&gt;)&lt;/li&gt;&lt;li&gt;Syrinx (&lt;a class=&quot;unknownlink&quot; href=&quot;Syrinx.html&quot; title=&quot;Pathfinder-RPG.syrinx&quot;&gt;syrinx&lt;/a&gt;)&lt;/li&gt;&lt;li&gt;Tanuki (&lt;a class=&quot;pagelink&quot; href=&quot;Tanuki.html&quot; title=&quot;Tanuki&quot;&gt;tanukis&lt;/a&gt;)&lt;/li&gt;&lt;li&gt;Tengu (&lt;a class=&quot;pagelink&quot; href=&quot;Tengu.html&quot; title=&quot;Tengu&quot;&gt;tengus&lt;/a&gt;)&lt;/li&gt;&lt;li&gt;Thriae (&lt;a class=&quot;pagelink&quot; href=&quot;Oracle-Thriae.html&quot; title=&quot;Thriae, Oracle thriae&quot;&gt;oracles thriae&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Reine-Thriae.html&quot; title=&quot;Thriae, Reine thriae&quot;&gt;reines thriae&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Soldat-Thriae.html&quot; title=&quot;Thriae, Soldat thriae&quot;&gt;soldats thriae&lt;/a&gt;)&lt;/li&gt;&lt;li&gt;Triaxien (&lt;a class=&quot;unknownlink&quot; href=&quot;Triaxien.html&quot; title=&quot;Pathfinder-RPG.triaxien&quot;&gt;triaxiens&lt;/a&gt;)&lt;/li&gt;&lt;li&gt;Vanara (&lt;a class=&quot;pagelink&quot; href=&quot;Vanara.html&quot; title=&quot;Vanara&quot;&gt;vanaras&lt;/a&gt;)&lt;/li&gt;&lt;li&gt;Verc&#233;sien (&lt;a class=&quot;unknownlink&quot; href=&quot;Verc&#233;sien.html&quot; title=&quot;Pathfinder-RPG.verc&#233;sien&quot;&gt;verc&#233;siens&lt;/a&gt;)&lt;/li&gt;&lt;li&gt;Vishkanyan (&lt;a class=&quot;pagelink&quot; href=&quot;Vishkanya-(Race).html&quot; title=&quot;Les vishkanyas&quot;&gt;vishkanyas&lt;/a&gt;)&lt;/li&gt;&lt;li&gt;Wayang (&lt;a class=&quot;pagelink&quot; href=&quot;Wayang-(Race).html&quot; title=&quot;Les wayangs&quot;&gt;wayangs&lt;/a&gt;)&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Les dialectes tribaux de Golarion&lt;a class=&quot;headeranchor&quot; id=&quot;Les_dialectes_tribaux_de_Golarion_1&quot; href=&quot;#Les_dialectes_tribaux_de_Golarion_1&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Il existe &#233;galement des dialectes tribaux.
&lt;ul&gt;&lt;li&gt;Kuru (dialecte propre aux tribus de kurus)&lt;/li&gt;&lt;li&gt;Polyglotte (nom donn&#233; &#224; un dialecte commun que les tribus du Mwangi, du Garund, des Manilles et de Sargava utilisent)&lt;/li&gt;&lt;li&gt;Shoanti (dialecte particulier des tribus de &lt;a class=&quot;externallink&quot; href=&quot;http://www.pathfinder-fr.org/Wiki/Golarion.Shoantis.ashx&quot; title=&quot;shoantis&quot; target=&quot;_blank&quot;&gt;shoantis&lt;/a&gt;)&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Les langues mortes de Golarion&lt;a class=&quot;headeranchor&quot; id=&quot;Les_langues_mortes_de_Golarion_2&quot; href=&quot;#Les_langues_mortes_de_Golarion_2&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;D&#39;autres langues d&#39;empires disparus peuvent &#233;galement &#234;tre parl&#233;es ou d&#233;couvertes dans les ruines de Golarion
&lt;ul&gt;&lt;li&gt;Azlant&lt;/li&gt;&lt;li&gt;T&#233;kritanin&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Le langage animal&lt;a class=&quot;headeranchor&quot; id=&quot;Le_langage_animal_3&quot; href=&quot;#Le_langage_animal_3&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;En th&#233;orie chaque type d&#39;animal poss&#232;de son propre langage.
&lt;ul&gt;&lt;li&gt;Actinopt&#233;rygien (poissons), dont l&#39;aboleth est d&#233;riv&#233;&lt;/li&gt;&lt;li&gt;Arachnid&#233; (araign&#233;es, scorpions), dont le girtablilu est d&#233;riv&#233;.&lt;/li&gt;&lt;li&gt;Aviaire (oiseaux), dont le strix, le tengu et le syrinx sont d&#233;riv&#233;s.&lt;/li&gt;&lt;li&gt;Batracien (grenouilles, crapauds), dont le grippli et le bourbi&#233;rin sont d&#233;riv&#233;s.&lt;/li&gt;&lt;li&gt;Bovid&#233; (vaches, antilopes)&lt;/li&gt;&lt;li&gt;Cam&#233;lid&#233; (chameaux, lamas)&lt;/li&gt;&lt;li&gt;Canin (chiens, loups), dont l&#39;adlet et le tanuki sont d&#233;riv&#233;s.&lt;/li&gt;&lt;li&gt;Cervid&#233; (chevreuils, cerfs)&lt;/li&gt;&lt;li&gt;C&#233;tac&#233; (baleines, dauphins)&lt;/li&gt;&lt;li&gt;Ch&#233;lonien (tortues, tortues marines)&lt;/li&gt;&lt;li&gt;Chiropt&#232;re (chauves-souris)&lt;/li&gt;&lt;li&gt;Chondrichthyen (squales)&lt;/li&gt;&lt;li&gt;Crustac&#233; (crabes, crevettes)&lt;/li&gt;&lt;li&gt;Dinosaure (les dinosaures)&lt;/li&gt;&lt;li&gt;&#201;quid&#233; (chevaux, z&#232;bres)&lt;/li&gt;&lt;li&gt;F&#233;lin (chats, lions), dont l&#39;huline et le sphinx sont d&#233;riv&#233;s.&lt;/li&gt;&lt;li&gt;Giraffid&#233; (girafes, okapis)&lt;/li&gt;&lt;li&gt;Hexapode (insectes), dont le d’ziriak, le thriae et le kasatha sont d&#233;riv&#233;s.&lt;/li&gt;&lt;li&gt;Insectivore (pangolins, fourmiliers)&lt;/li&gt;&lt;li&gt;Marsupial (kangourous, koalas)&lt;/li&gt;&lt;li&gt;M&#233;gafaune (les animaux de la m&#233;gafaune qui n&#39;ont pas de descendants)&lt;/li&gt;&lt;li&gt;Mollusque (escargots, pieuvres)&lt;/li&gt;&lt;li&gt;Myriapode (milles-pattes, glomeris)&lt;/li&gt;&lt;li&gt;Ophidien (serpents), dont le vishkanya est d&#233;riv&#233;.&lt;/li&gt;&lt;li&gt;Ovid&#233; (moutons, ch&#232;vres)&lt;/li&gt;&lt;li&gt;Pachyderme (&#233;l&#233;phants, hippopotames)&lt;/li&gt;&lt;li&gt;Pinnip&#232;de (phoques, morses)&lt;/li&gt;&lt;li&gt;Plantigrade (ours, gloutons), le gnoll &#233;tant d&#233;riv&#233; d&#39;un m&#233;lange de plantigrade de f&#233;lin et de canid&#233;.&lt;/li&gt;&lt;li&gt;Primate (singes, gorilles), dont le vanara et le sasquatch sont d&#233;riv&#233;s.&lt;/li&gt;&lt;li&gt;Rongeur (&#233;cureuils, lapins)&lt;/li&gt;&lt;li&gt;Squamate (l&#233;zards, crocodiles), dont le draconien et le reptoide sont d&#233;riv&#233;s.&lt;/li&gt;&lt;li&gt;Suid&#233; (sangliers, cochons)&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Le langage des plantes&lt;a class=&quot;headeranchor&quot; id=&quot;Le_langage_des_plantes_4&quot; href=&quot;#Le_langage_des_plantes_4&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;De m&#234;me, il semblerait qu&#39;il existe des langages propres aux plantes.
&lt;ul&gt;&lt;li&gt;Algues&lt;/li&gt;&lt;li&gt;Arbres&lt;/li&gt;&lt;li&gt;Attrapes-mouches&lt;/li&gt;&lt;li&gt;Calebasses&lt;/li&gt;&lt;li&gt;Champignons&lt;/li&gt;&lt;li&gt;Lotus&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;
